-- Baked from pixelfx/src/fx/jutsu (15-20 fps per move, seals + character + effect + target), uploaded 2026-11-20..22.
-- J(key, char, title, name, desc, rgb, frameW, frameH, cols, feetX, feetY, {assetId, frames, ...}, {{frame, sfx}, ...})
local D = {}
local function J(key, char, title, name, desc, rgb, fw, fh, cols, fx, fy, list, sfx, cam, fps)
	local c = nil
	if cam then
		c = {}
		for z, x, y, r in string.gmatch(cam, "([%d%.%-]+),([%d%.%-]+),([%d%.%-]+),([%d%.%-]+)") do c[#c + 1] = { tonumber(z), tonumber(x), tonumber(y), tonumber(r) } end
	end
	local s = {}
	for i = 1, #list, 2 do s[#s + 1] = { id = string.format("rbxassetid://%.0f", list[i]), n = list[i + 1] } end
	D[#D + 1] = { key = key, char = char, title = title, name = name, desc = desc, color = Color3.fromRGB(rgb[1], rgb[2], rgb[3]), fps = fps or 15, fw = fw, fh = fh, cols = cols, feet = { fx, fy }, sheets = s, sfx = sfx or {}, cam = c }
end
